css:
/* 终端：昼夜双版（:root 为日间基线，[data-reader-theme="night"] 覆盖夜景）；正文区占页高 80%+（蓝图硬约束①） */
:root{
  --tm-bg:#f2f4f6; --tm-panel:#e8ecef; --tm-fg:#12241c; --tm-dim:#5c6b64;
  --tm-green:#0f7a4d; --tm-amber:#9a6400; --tm-line:rgba(15,122,77,.30);
}
[data-reader-theme="night"]{
  --tm-bg:#05080a; --tm-panel:#0b1210; --tm-fg:#c8f7dc; --tm-dim:#4e6b5e;
  --tm-green:#3ddc84; --tm-amber:#ffcc66; --tm-line:rgba(61,220,132,.34);
}
html,body{margin:0;padding:0;background:var(--tm-bg);color:var(--tm-fg);
  font-family:"JetBrains Mono","DejaVu Sans Mono",Consolas,monospace;
  font-size:var(--md-font-size,18px);line-height:var(--md-line-height,1.7);}
body::before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.5;
  background:repeating-linear-gradient(180deg,transparent 0 22px,var(--tm-line) 22px 23px);}
.tm-head{position:relative;display:flex;gap:.6em;align-items:baseline;justify-content:space-between;
  padding:.55em 1em .45em;font-size:.76em;color:var(--tm-dim);background:var(--tm-panel);
  border-bottom:1px solid var(--tm-line);}
.tm-path{color:var(--tm-green);}
.tm-chapter{flex:1 1 auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.tm-pct{color:var(--tm-amber);font-variant-numeric:tabular-nums;}
.tm-cmd{position:relative;display:flex;gap:.5em;align-items:center;padding:.7em 1em .2em;font-size:.86em;color:var(--tm-dim);}
.tm-caret{width:.55em;height:1.05em;background:var(--tm-green);}
.tm-cmd-text{color:var(--tm-fg);}
.tm-body{position:relative;padding:.7em 1em 0;}
.tm-body .reader-chapter-title{margin:0 0 .6em;font-size:1.25em;font-weight:700;color:var(--tm-green);}
.tm-body .reader-chapter-title::before{content:"# ";color:var(--tm-dim);}
.tm-body .reader-paragraph{margin:0 0 .8em;}
.tm-body p{margin:0 0 .8em;}
.tm-body a{color:var(--tm-green);text-decoration:none;border-bottom:1px dashed var(--tm-line);}
.tm-body blockquote{margin:0 0 .85em;padding:.4em .8em;border-left:2px solid var(--tm-amber);color:var(--tm-dim);}
.tm-body code{background:rgba(127,127,127,.16);padding:.12em .34em;border-radius:2px;}
.tm-body pre{background:rgba(127,127,127,.12);padding:.75em;border-radius:3px;overflow-x:auto;border-left:2px solid var(--tm-line);}
.tm-body table{width:100%;border-collapse:collapse;}
.tm-body th,.tm-body td{border:1px solid var(--tm-line);padding:.32em .5em;}
.tm-foot{position:relative;display:flex;justify-content:space-between;gap:.8em;
  padding:.5em 1em .6em;font-size:.72em;color:var(--tm-dim);font-variant-numeric:tabular-nums;
  border-top:1px solid var(--tm-line);background:var(--tm-panel);}
@media (prefers-reduced-motion:reduce){.tm-caret{opacity:1;}}

javascript:
(function () {
  'use strict';
  // 每页动效。只使用双方共有的 readerTemplate 钩子 API + Web Animations
  // => 同一份主题在我们与 archive 两个引擎上行为一致（互兼容目标）。
  var anims = [], active = null;
  function stop() {
    for (var i = 0; i < anims.length; i++) { anims[i].cancel(); }
    anims = []; active = null;
  }
  function play(node, frames, dur, delay, easing) {
    if (!node || typeof node.animate !== 'function') return;
    anims.push(node.animate(frames, {
      duration: dur, delay: delay || 0, iterations: Infinity, easing: easing || 'ease-in-out'
    }));
  }
  function all(root, sel) {
    return root ? Array.prototype.slice.call(root.querySelectorAll(sel)) : [];
  }
  function start(page) {
    active = page;
    // 小视口不做装饰动效（与 archive 主题同判据，避免小窗下动效抢帧）
    if (readerTemplate.viewport.height <= 440) return;
    var i;

    // 终端：光标硬闪（steps）+ 状态行脉动
    var caret = page.querySelector('.tm-caret');
    if (caret) play(caret, [{ opacity: 1 }, { opacity: 0 }, { opacity: 1 }], 1100, 0, 'steps(1, end)');
    var labels = all(page, '.tm-pct, .tm-path');
    for (i = 0; i < labels.length; i++) {
      play(labels[i], [{ opacity: 0.6 }, { opacity: 1 }, { opacity: 0.6 }], 1800, -i * 250);
    }
    play(page.querySelector('.tm-head'), [{ opacity: 0.75 }, { opacity: 1 }, { opacity: 0.75 }], 3000);
  }
  // 结算后旧节点可能已脱离文档 => 先停旧动画（换壳/重排后由 motionChange 重新起）
  readerTemplate.on('afterLayout', function () { stop(); });
  readerTemplate.on('motionChange', function (event) {
    if (!event.page || event.state === 'settled' || event.reducedMotion) { stop(); return; }
    if (event.state === 'paused') {
      for (var i = 0; i < anims.length; i++) { anims[i].pause(); }
      return;
    }
    if (active === event.page) {
      for (var j = 0; j < anims.length; j++) { anims[j].play(); }
      return;
    }
    stop(); start(event.page);
  });
  readerTemplate.on('dispose', stop);
})();
